import re
from thefuck.utils import replace_argument
from thefuck.specific.git import git_support


@git_support
def match(command):
    has_push = 'push' in command.script_parts
    has_upstream = 'set-upstream' in command.output
    return has_push and has_upstream


def _find_upstream_flag_position(parts):
    for flag in ('--set-upstream', '-u'):
        if flag in parts:
            return parts.index(flag)
    return None


@git_support
def get_new_command(command):
    # If --set-upstream or -u are passed, remove it and its argument. This is
    # because the remaining arguments are concatenated onto the command suggested
    # by git, which includes --set-upstream and its argument
    parts = list(command.script_parts)
    flag_pos = _find_upstream_flag_position(parts)

    if flag_pos is not None:
        del parts[flag_pos]

        # In case of `git push -u` we don't have next argument:
        if flag_pos < len(parts):
            del parts[flag_pos]
    else:
        # the only non-qualified permitted options are the repository and refspec; git's
        # suggestion include them, so they won't be lost, but would be duplicated otherwise.
        idx = parts.index('push') + 1
        while len(parts) > idx and not parts[-1].startswith('-'):
            parts.pop()

    suggested = re.findall(r'git push (.*)', command.output)[0]
    suggested = suggested.replace("'", r"\'").strip()
    return replace_argument(" ".join(parts), 'push',
                            'push {}'.format(suggested))

